// Regenerates lib/neighbourhood-editorial/generated.ts (imports of every data file). Run after adding or changing a data file:
//   node scripts/gen-neighbourhood-editorial.mjs
// tests/neighbourhood-editorial.test.ts fails when the generated file is out of date.
import { readdirSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";

const root = path.resolve(new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
const dataDir = path.join(root, "lib", "neighbourhood-editorial", "data");
mkdirSync(dataDir, { recursive: true });
const files = readdirSync(dataDir).filter((f) => f.endsWith(".json")).sort();
const text = files.filter((f) => f !== "photos-hoods.json");
const ident = (f) => "d_" + f.replace(/\.json$/, "").replace(/[^a-zA-Z0-9]/g, "_");
let ts = "// GENERATED by scripts/gen-neighbourhood-editorial.mjs: do not edit by hand.\n";
ts += 'import type { Photo } from "../types";\nimport type { NeighbourhoodEditorial } from "./types";\n';
for (const f of files) ts += `import ${ident(f)} from "./data/${f}";\n`;
ts += `\nexport const editorials: NeighbourhoodEditorial[] = [${text.map((f) => `${ident(f)} as unknown as NeighbourhoodEditorial`).join(", ")}];\n`;
ts += files.includes("photos-hoods.json")
  ? `export const hoodPhotos: Record<string, Photo> = ${ident("photos-hoods.json")} as unknown as Record<string, Photo>;\n`
  : "export const hoodPhotos: Record<string, Photo> = {};\n";
writeFileSync(path.join(root, "lib", "neighbourhood-editorial", "generated.ts"), ts);
console.log(`generated: ${text.length} editorial file(s), ${files.includes("photos-hoods.json") ? "with" : "no"} hero registry`);
